import React, { useState, useEffect } from "react";
import "./AdminCommon.css";
import "./AnalyticsDashboard.css";

const AnalyticsDashboard = () => {
  const [analytics, setAnalytics] = useState({});
  const [totalVisits, setTotalVisits] = useState(0);

  useEffect(() => {
    const data = JSON.parse(localStorage.getItem("analytics") || "{}");
    setAnalytics(data);

    // Calculate total visits
    const total = Object.values(data).reduce(
      (sum, page) => sum + (page.visits || 0),
      0,
    );
    setTotalVisits(total);
  }, []);

  const formatDate = (dateString) => {
    if (!dateString) return "Never";
    return new Date(dateString).toLocaleString();
  };

  const sortedPages = Object.entries(analytics).sort(
    (a, b) => b[1].visits - a[1].visits,
  );

  return (
    <div className="admin-page analytics-dashboard">
      <h2>📊 Analytics Dashboard</h2>

      <div className="analytics-summary">
        <div className="summary-card">
          <h3>{totalVisits}</h3>
          <p>Total Page Views</p>
        </div>
        <div className="summary-card">
          <h3>{Object.keys(analytics).length}</h3>
          <p>Unique Pages</p>
        </div>
        <div className="summary-card">
          <h3>{sortedPages.length > 0 ? sortedPages[0][0] : "No data"}</h3>
          <p>Most Visited Page</p>
        </div>
      </div>

      <div className="analytics-table-container">
        <h3>Page Visit Statistics</h3>
        <table className="analytics-table">
          <thead>
            <tr>
              <th>Page</th>
              <th>Visits</th>
              <th>First Visit</th>
              <th>Last Visit</th>
            </tr>
          </thead>
          <tbody>
            {sortedPages.length > 0 ? (
              sortedPages.map(([page, data]) => (
                <tr key={page}>
                  <td>{page}</td>
                  <td>{data.visits}</td>
                  <td>{formatDate(data.firstVisit)}</td>
                  <td>{formatDate(data.lastVisit)}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="4" style={{ textAlign: "center" }}>
                  No analytics data available
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="analytics-actions">
        <button
          className="admin-btn admin-btn-secondary"
          onClick={() => {
            if (
              window.confirm(
                "Are you sure you want to clear all analytics data?",
              )
            ) {
              localStorage.removeItem("analytics");
              setAnalytics({});
              setTotalVisits(0);
            }
          }}
        >
          <i className="fas fa-trash"></i> Clear Analytics Data
        </button>
      </div>
    </div>
  );
};

export default AnalyticsDashboard;
